def solve(keys, values, new_keys, new_values, capacity):
    if capacity<0 or len(keys)!=len(values) or len(new_keys)!=len(new_values):raise ValueError("invalid cache")
    rows=list(keys)+list(new_keys); vals=list(values)+list(new_values)
    if rows:
        kd=len(rows[0]);vd=len(vals[0])
        if any(len(r)!=kd for r in rows) or any(len(r)!=vd for r in vals):raise ValueError("shape mismatch")
    start=max(0,len(rows)-capacity)
    return [list(r) for r in rows[start:]],[list(r) for r in vals[start:]],len(keys)+len(new_keys)-len(rows[start:])
